from .rf_switch_factory import RfSwitchFactory


class RfSwitchFacade:
    def __init__(self):
        self.rf_switch = None

    def setup_rf_switch(self, **kwargs):
        def verify_parameters():
            if 'rf_switch' not in kwargs:
                required_params = {'ip', 'vendor'}
                missing_params = required_params - set(kwargs.keys())
                if missing_params:
                    msg = 'Expected parameters not passed: {}'
                    msg.format(', '.join(str(arg) for arg in missing_params))
                    raise RuntimeError(msg)

        verify_parameters()

        self.rf_switch = RfSwitchFactory.create(**kwargs)

    def connect_ports(self, port_in, port_out="1"):
        self.rf_switch.connect_ports(port_in, port_out)

    def disconnect_ports(self, port_in, port_out="1"):
        self.rf_switch.disconnect_ports(port_in, port_out)

    def get_port_in_status(self, port_in):
        return self.rf_switch.get_port_in_status(port_in)

    def get_port_out_status(self, port_out):
        return self.rf_switch.get_port_out_status(port_out)

    def get_connected_ports(self):
        return self.rf_switch.get_connected_ports()
